import torch
import torch.nn as nn

class PostNormBlock(nn.Module):
    def __init__(self, d):
        super().__init__()
        self.f, self.norm = nn.Linear(d, d), nn.LayerNorm(d)
    def forward(self, x):
        return self.norm(x + self.f(x))       # norm on the residual path

class PreNormBlock(nn.Module):
    def __init__(self, d):
        super().__init__()
        self.f, self.norm = nn.Linear(d, d), nn.LayerNorm(d)
    def forward(self, x):
        return x + self.f(self.norm(x))       # clean identity path

d, depth = 64, 48
pre = nn.Sequential(*[PreNormBlock(d) for _ in range(depth)], nn.LayerNorm(d))
post = nn.Sequential(*[PostNormBlock(d) for _ in range(depth)])
for name, net in [("pre", pre), ("post", post)]:
    x = torch.randn(8, d, requires_grad=True)
    net(x).sum().backward()
    print(name, x.grad.norm().item())         # gradient reaching the input
